import httpx
from pydantic import BaseModel, ValidationError

class WeatherResponse(BaseModel):
    temperature_celsius: float
    humidity_percent: float

def fetch_weather(city: str) -> WeatherResponse:
    response = httpx.get(f"https://api.example.com/weather/{city}", timeout=3.0)
    response.raise_for_status()
    try:
        return WeatherResponse.model_validate(response.json())
    except ValidationError as error:
        raise RuntimeError(f"Contrat API rompu pour {city}: {error}") from error
